WITH exploded AS (SELECT id, service, host, log_ts, latency_ms, status_code, k, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS k, v), unpacked AS (SELECT log_ts, latency_ms, status_code, v, SHIFTRIGHT(status_code, 2) AS status_code_high, CAST((status_code & 2) != 0 AS INT) AS is_flagged FROM exploded), with_windows AS (SELECT *, RANK() OVER w_hist is_flagged_rank, SUM(latency_ms) OVER w_recent latency_ms_sum_15m, CUME_DIST() OVER w_grp status_code_high_cume_dist, COUNT(status_code_high) OVER w_recent status_code_high_count_15m FROM unpacked WHERE status_code_high = 2 WINDOW w_hist AS (ORDER BY is_flagged DESC), w_recent AS (ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW), w_grp AS (ORDER BY status_code_high DESC NULLS FIRST)), valid AS (SELECT *, ROUND(status_code / latency_ms, 2) status_code_per_latency_ms, status_code_high_cume_dist * is_flagged_rank status_code_high_cume_dist_times_is_flagged_rank FROM with_windows WHERE log_ts > TIMESTAMP '2025-06-01 14:00:00') SELECT latency_ms, v, status_code_high, is_flagged, is_flagged_rank, status_code_high_count_15m, status_code_per_latency_ms, status_code_high_cume_dist_times_is_flagged_rank, MAX(status_code_high_cume_dist) OVER (ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) status_code_high_cume_dist_max_15m, AVG(status_code_per_latency_ms) OVER w_recent status_code_per_latency_ms_avg_2h, RANK() OVER (ORDER BY status_code_per_latency_ms DESC) status_code_per_latency_ms_rank FROM valid WINDOW w_recent AS (ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 7200 PRECEDING AND CURRENT ROW)
